import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Languages — Any Language the Job Needs","description":"Python, JavaScript/TypeScript, Go, PHP, C#, SQL, C/C++ and PLC languages — honest production readiness across nine languages.","frontmatter":{"title":"Languages — Any Language the Job Needs","description":"Python, JavaScript/TypeScript, Go, PHP, C#, SQL, C/C++ and PLC languages — honest production readiness across nine languages."},"headers":[],"relativePath":"en/skills/languages/index.md","filePath":"en/skills/languages/index.md"}`),a={name:`en/skills/languages/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="languages-—-any-language-the-job-needs" tabindex="-1">Languages — Any Language the Job Needs <a class="header-anchor" href="#languages-—-any-language-the-job-needs" aria-label="Permalink to “Languages — Any Language the Job Needs”">​</a></h1><p>I refuse the &quot;one true language&quot; religion. Languages are tools with shapes, and the job decides which shape fits. These percentages are honest self-assessments of production readiness — not course certificates.</p><table tabindex="0"><thead><tr><th>Language</th><th>Readiness</th><th>Where I use it</th></tr></thead><tbody><tr><td>Python</td><td>99%</td><td>API bridges, agents, automation, scrapers — GhostBrain, Hermes, panels.</td></tr><tr><td>JavaScript / TypeScript</td><td>98%</td><td>Full-stack web, edge Workers, panels, this portfolio.</td></tr><tr><td>PHP</td><td>98%</td><td>Laravel services, classic deploys, quick client products.</td></tr><tr><td>SQL</td><td>100%</td><td>Schema design, tuning, reporting across Postgres/MySQL.</td></tr><tr><td>Ladder (LD)</td><td>96%</td><td>PLC logic on real production lines.</td></tr><tr><td>Structured Text (ST)</td><td>96%</td><td>IEC 61131-3 industrial control programs.</td></tr><tr><td>Go</td><td>94%</td><td>NetPilot, OmniRouter, glm-free-api — CLIs and services.</td></tr><tr><td>C#</td><td>93%</td><td>.NET backends, desktop tools, WPF/MAUI.</td></tr><tr><td>C / C++</td><td>78%</td><td>HardwarePT, embedded experiments, performance cores.</td></tr></tbody></table><p>The pattern behind the list: high-level languages for velocity, systems languages for control, and industrial languages because somebody has to make the physical world behave. New languages are a weekend problem, not a career decision — the <a href="/Usf/en/agentic/overview/">agentic workflow</a> makes ramp-up even cheaper, since agents write idiomatic scaffolding in any ecosystem while I supply the judgment.</p>`,4)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};